      "feeder": {
        "title": "喂食提醒",
        "todayAmount": 0,
        "unit": "g",
        "status": "已完成",
        "nextHint": "等待今日日程",
        "actionText": "补粮",
        "icon": "resources/base/media/icon_schedule.png"
