      "data": {
        "calendar": {
          "items": []
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "pet_feeder_schedule",
      "src": "resources/base/media/icon_schedule.png",
      "use": "feeding reminder glyph",
      "description": "日程提醒图标，用于表达宠物喂食提醒与今日日历安排。",
      "bindTo": "/feeder/icon",
      "static": true
    }
  ]
}

